import Screenshot from"../../Screenshot/Screenshot.js";if(Screenshot.isSupported()){$(".document_item .upload-from-section").removeClass("d-none");$(".document_item .fileupload").each(((e,n)=>{Screenshot.listenOnFileUpload(n)}));const e=$('.document_item button[name="add_screenshot"]');const n=$('.document_item button[name="add_screenrecording"]');const t=$('.document_item button[name="stop_recording"]');const o=$("#screen_capture_preview");e.removeClass("d-none");n.removeClass("d-none");e.on("click",(()=>{t.addClass("d-none");Screenshot.captureScreenshot().then((e=>{const n=o.find(".previews").children().length;const t=`screenshot${n}.png`;Screenshot.appendPreviewImg(o.find(".previews"),e,"200px",t);e.toBlob((n=>{n.name=t;window.uploadFile(n,{getElement:()=>o.get(0)});e.remove()}),"image/png")}))}));n.on("click",(()=>{const e=[];Screenshot.startRecording().then((n=>{t.removeClass("d-none");n.ondataavailable=n=>{e.push(n.data);const t=o.find(".previews").children().length;const s=`screen_capture${t}.webm`;n.data.name=s;Screenshot.appendPreviewVideo(o.find(".previews"),n.data,"200px",s);window.uploadFile(n.data,{getElement:()=>o.get(0)})};t.on("click",(()=>{n.stop();n.stream.getTracks().forEach((e=>e.stop()));t.addClass("d-none")}))}))}))}